"const https = require('https');

function fetch(url) {
  https.get(url, { headers: { 'User-Agent': 'Mozilla/5.0' } }, (res) => {
    if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location) {
      let loc = res.headers.location;
      if (loc.startsWith('/')) loc = 'https://dev.to' + loc;
      return fetch(loc);
    }
    let data = '';
    res.on('data', chunk => data += chunk);
    res.on('end', () => {
      console.log('Fetched length:', data.length);
      const matches = [...data.matchAll(/id="(best-use-of-[^"]+)"[\s\S]*?<h3>(.*?)<\/h3>[\s\S]*?<p[^>]*>([\s\S]*?)<\/p>/gi)];
      console.log('Matches found:', matches.length);
      matches.forEach(m => {
        console.log('ID:', m[1]);
        console.log('Title:', m[2].replace(/<[^>]+>/g, '').trim());
        console.log('Desc:', m[3].replace(/<[^>]+>/g, '').trim());
        console.log('---');
      });
    });
  }).on('error', err => console.error(err));
}
fetch('https://dev.to/challenges/hf26');
"

